package main

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

// TestReferenceDrift is the freshness gate for the committed reference
// files: one whole-catalog generation must reproduce every committed file
// byte-identically, every generated file must be committed, and no
// committed reference file may be orphaned (generated by nothing). The
// invariant is total -- every registered catalog kind ships a fresh page --
// so a new kind or provider added without regenerating fails the gate.
//
// On drift: PLANTON_REGEN_REFERENCE=1 go test ./pkg/explain/refgen -run TestReferenceDrift
// (or `make generate-reference`).
func TestReferenceDrift(t *testing.T) {
	root := repoRoot(t)
	summary, err := Generate(root)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	// A broken hack manifest silently thins the committed page (its Example
	// disappears on the next regeneration) -- fail loudly instead.
	for _, invalid := range summary.InvalidManifests {
		t.Errorf("%s: hack manifest fails validation (a catalog bug): %v", invalid.Kind, invalid.Err)
	}

	regen := os.Getenv("PLANTON_REGEN_REFERENCE") != ""
	for _, path := range summary.SortedPaths() {
		want := summary.Files[path]
		target := filepath.Join(root, path)
		if regen {
			if err := os.WriteFile(target, []byte(want), 0644); err != nil {
				t.Fatalf("write %s: %v", target, err)
			}
			continue
		}
		got, err := os.ReadFile(target)
		if err != nil {
			t.Errorf("%s is generated but not committed -- run `make generate-reference`: %v", path, err)
			continue
		}
		if string(got) != want {
			t.Errorf("%s is out of sync with the schema -- run `make generate-reference`", path)
		}
	}

	for _, path := range committedReferenceFiles(t, root) {
		if _, ok := summary.Files[path]; !ok {
			t.Errorf("%s is committed but no longer generated (kind removed or renamed?) -- delete it", path)
		}
	}
}

// committedReferenceFiles lists every committed generator-owned file, so the
// gate catches orphans in both directions. Patterns mirror the generator's
// output layout (kind pages at <provider>/<kind>/<version>/, catalog files
// at the provider root and per provider).
func committedReferenceFiles(t *testing.T, root string) []string {
	t.Helper()
	providerRoot := filepath.Join(root, "apis", providerPathPrefix)
	var files []string
	for _, pattern := range []string{
		filepath.Join(providerRoot, "*", "*", "*", "reference.md"),
		filepath.Join(providerRoot, "*", "reference-index.md"),
		filepath.Join(providerRoot, "reference-index.md"),
		filepath.Join(providerRoot, "reference-graph.yaml"),
		filepath.Join(providerRoot, "reference-commons.md"),
	} {
		matches, err := filepath.Glob(pattern)
		if err != nil {
			t.Fatal(err)
		}
		for _, match := range matches {
			rel, err := filepath.Rel(root, match)
			if err != nil {
				t.Fatal(err)
			}
			files = append(files, rel)
		}
	}
	return files
}

// repoRoot walks up from this test file to the directory containing go.mod.
// Under the Bazel sandbox the checkout (and its committed reference files)
// is not available, so the gate runs via plain `go test` and skips
// explicitly under Bazel.
func repoRoot(t *testing.T) string {
	t.Helper()
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	dir := filepath.Dir(thisFile)
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			if os.Getenv("TEST_WORKSPACE") != "" {
				t.Skip("skipping drift gate under the Bazel sandbox: the repo checkout is not available; the gate runs via `go test`")
			}
			t.Fatal("could not locate repo root (go.mod)")
		}
		dir = parent
	}
}
